"""Helpers for reporting installed distribution versions."""

from importlib import metadata
from typing import Optional


def _normalize_name(name: str) -> str:
    return str(name).lower().replace("_", "-").replace(".", "-")


def _installed_distributions():
    """Yield installed distributions with normalized names and versions."""
    for dist in metadata.distributions():
        dist_name = dist.metadata.get("Name") or ""
        yield _normalize_name(dist_name), dist.version


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each requested distribution name to the installed version string, or None.

    Matching is case-insensitive and follows standard distribution-name normalization.
    The keys in the returned dict are exactly the input names.
    """
    installed = {}
    for dist_name, version in _installed_distributions():
        if dist_name:
            installed[dist_name] = version

    report: dict[str, Optional[str]] = {}
    for name in names:
        report[name] = installed.get(_normalize_name(name))
    return report

